def select_platform_resource(model_type: str = "chat") -> str:
    if model_type == "chat":
        return "gpt-4o"  # OpenAI's flagship model
    elif model_type == "embedding":
        return "text-embedding-3-small"
    elif model_type == "moderation":
        return "text-moderation-latest"
    elif model_type == "tts":
        return "tts-1"
    return "gpt-3.5-turbo"

import os
from openai import OpenAI

def get_openai_client():
    return OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
        organization=os.environ.get("OPENAI_ORGANIZATION_ID"),
    )

def format_chat_messages(user_content: str, system_content: str | None = None):
    messages = []
    if system_content:
        messages.append({"role": "system", "content": system_content})
    messages.append({"role": "user", "content": user_content})
    return messages

def extract_content_from_openai_response(response):
    if response and response.choices and response.choices[0].message:
        return response.choices[0].message.content
    return None
